var Finance = function () {};
Finance.prototype.AM = function (principal, rate, period, yearOrMonth) {
  var ratePerPeriod = yearOrMonth === 1 ? rate / 12 / 100 : rate / 100;
  return Math.round((principal * (ratePerPeriod * Math.pow(1 + ratePerPeriod, period))) / (Math.pow(1 + ratePerPeriod, period) - 1) * 100) / 100;
};
Finance.prototype.CI = function (rate, compoundingsPerYear, principal, numberOfYears) {
  var ratePerPeriod = rate / 100 / compoundingsPerYear;
  return Math.round(principal * Math.pow(1 + ratePerPeriod, compoundingsPerYear * numberOfYears) * 100) / 100;
};
Finance.prototype.CAGR = function (beginningValue, endingValue, numberOfPeriods) {
  return Math.round((Math.pow(endingValue / beginningValue, 1 / numberOfPeriods) - 1) * 10000) / 100;
};
Finance.prototype.FV = function (rate, numberOfPeriods, payment, presentValue, type) {
  type = type || 0;
  var r = rate / 100;
  if (r === 0) return -(presentValue + numberOfPeriods * payment);
  var x = Math.pow(1 + r, numberOfPeriods);
  return -((presentValue * x) + (payment * (1 + r * type) * (x - 1) / r));
};
Finance.prototype.PV = function (rate, numberOfPeriods, payment, futureValue, type) {
  type = type || 0;
  var r = rate / 100;
  if (r === 0) return -(futureValue + numberOfPeriods * payment);
  var x = Math.pow(1 + r, numberOfPeriods);
  return -((futureValue / x) + (payment * (1 + r * type) * (x - 1) / (r * x)));
};
Finance.prototype.IRR = function (cfs) {
  var min = -1.0, max = 1.0, guess = 0.1;
  for (var i = 0; i < 1000; i++) {
    var npv = 0;
    for (var j = 0; j < cfs.length; j++) {
      npv += cfs[j] / Math.pow(1 + guess, j);
    }
    if (Math.abs(npv) < 0.00001) return Math.round(guess * 10000) / 100;
    if (npv > 0) min = guess;
    else max = guess;
    guess = (min + max) / 2;
  }
  return Math.round(guess * 10000) / 100;
};
if (typeof module !== 'undefined' && module.exports) module.exports = Finance;
if (typeof window !== 'undefined') window.Finance = Finance;